@page "/catalog"
@using sv_00463ceaaea64e6d989d3ce9c4a98d2c.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (isLoading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-link" @onclick="LoadDataAsync">Retry</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-3">
            <CatalogFilters Categories="categories" OnApplyFilters="HandleFiltersApplied" />
        </div>
        <div class="col-md-9">
            <CatalogToolbar SortBy="@sortBy"
                            StartItem="@startItem"
                            EndItem="@endItem"
                            TotalCount="@totalCount"
                            OnSortChanged="HandleSortChanged" />

            @if (products.Count == 0)
            {
                <div class="alert alert-info text-center">
                    No products found matching your criteria.
                </div>
            }
            else
            {
                <ProductGrid Products="products"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                @if (totalPages > 1)
                {
                    <div class="mt-4">
                        <CatalogPagination CurrentPage="currentPage"
                                           TotalPages="totalPages"
                                           OnPageChanged="HandlePageChanged" />
                    </div>
                }
            }
        </div>
    </div>
}

@code {
    private List<Product> products = [];
    private List<string> categories = [];
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;
    private int startItem;
    private int endItem;
    private bool isLoading = true;
    private string? errorMessage;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            categories = await ProductService.GetCategoriesAsync();
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchProducts()
    {
        var result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
        products = result.Items;
        totalCount = result.TotalCount;
        totalPages = (int)Math.Ceiling((double)totalCount / pageSize);
        if (totalPages < 1) totalPages = 1;
        startItem = totalCount == 0 ? 0 : (currentPage - 1) * pageSize + 1;
        endItem = Math.Min(currentPage * pageSize, totalCount);
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        try
        {
            errorMessage = null;
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        try
        {
            errorMessage = null;
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        try
        {
            errorMessage = null;
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

